  @ffi.Uint32()
  external int max_attempts;

  @ffi.Uint32()
  external int base_delay_ms;

  @ffi.Uint32()
  external int max_delay_ms;
}

/// Event metadata. Buffers are copied into caller memory by mqtt_client_poll.
final class MqttEvent extends ffi.Struct {
  @ffi.Uint32()
  external int kind;

  @ffi.Int32()
  external int code;

  @ffi.Uint64()
  external int operation_id;

  @ffi.Uint16()
  external int packet_id;

  @ffi.Uint8()
  external int qos;

  @ffi.Uint8()
  external int session_present;

  @ffi.Size()
  external int topic_len;

  @ffi.Size()
  external int payload_len;
}

typedef MqttNativeFreeFunction = ffi.Void Function(ffi.Pointer<ffi.Void>);
typedef DartMqttNativeFreeFunction = void Function(ffi.Pointer<ffi.Void>);

/// Native allocator deallocator, never a Dart trampoline.
typedef MqttNativeFree
    = ffi.Pointer<ffi.NativeFunction<MqttNativeFreeFunction>>;
